SELECT jsonb_agg(jsonb_build_object('table',table_name,'count',row_count,'sha256',row_sha) ORDER BY table_name) FROM (SELECT 'app.access_audit_logs' AS table_name,count(*) AS row_count,encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text,'UTF8')),'hex') AS row_sha FROM app.access_audit_logs t UNION ALL SELECT 'app.age_gate_attempts' AS table_name,count(*) AS row_count,encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text,'UTF8')),'hex') AS row_sha FROM app.age_gate_attempts t UNION ALL SELECT 'app.age_gate_blocks' AS table_name,count(*) AS row_count,encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text,'UTF8')),'hex') AS row_sha FROM app.age_gate_blocks t UNION ALL SELECT 'app.audit_events' AS table_name,count(*) AS row_count,encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text,'UTF8')),'hex') AS row_sha FROM app.audit_events t UNION ALL SELECT 'app.auth_provider_accounts' AS table_name,count(*) AS row_count,encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text,'UTF8')),'hex') AS row_sha FROM app.auth_provider_accounts t UNION ALL SELECT 'app.candidate_profiles' AS table_name,count(*) AS row_count,encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text,'UTF8')),'hex') AS row_sha FROM app.candidate_profiles t UNION ALL SELECT 'app.consent_content_revision' AS table_name,count(*) AS row_count,encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text,'UTF8')),'hex') AS row_sha FROM app.consent_content_revision t UNION ALL SELECT 'app.consent_disposition' AS table_name,count(*) AS row_count,encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text,'UTF8')),'hex') AS row_sha FROM app.consent_di