g(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text,'UTF8')),'hex') AS row_sha FROM platform.owner_mutation_evidence t UNION ALL SELECT 'platform.runtime_attempt' AS table_name,count(*) AS row_count,encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text,'UTF8')),'hex') AS row_sha FROM platform.runtime_attempt t UNION ALL SELECT 'platform.runtime_command_receipt' AS table_name,count(*) AS row_count,encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text,'UTF8')),'hex') AS row_sha FROM platform.runtime_command_receipt t UNION ALL SELECT 'platform.runtime_effect_receipt' AS table_name,count(*) AS row_count,encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text,'UTF8')),'hex') AS row_sha FROM platform.runtime_effect_receipt t UNION ALL SELECT 'platform.runtime_inbox_receipt' AS table_name,count(*) AS row_count,encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text,'UTF8')),'hex') AS row_sha FROM platform.runtime_inbox_receipt t UNION ALL SELECT 'platform.runtime_outbox_message' AS table_name,count(*) AS row_count,encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text,'UTF8')),'hex') AS row_sha FROM platform.runtime_outbox_message t UNION ALL SELECT 'platform.runtime_reservation' AS table_name,count(*) AS row_count,encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text,'UTF8')),'hex') AS row_sha FROM platform.runtime_reservation t UNION ALL SELECT 'platform.runtime_work_item' AS table_name,count(*) AS row_count,encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb)::text,'UTF8')),'hex') AS row_sha FROM platform.runtime_work_item t UNION ALL SELECT 'platform_private.identity_service_authorization' AS table_name,count(*) AS row_count,encode(